// ─── Open-Meteo Air Quality API ───────────────────────────────────────────────

interface AqiData {
  current: {
    pm2_5:         number;
    pm10:          number;
    european_aqi:  number;
    us_aqi:        number;
  };
}

function aqiLabel(aqi: number): { label: string; color: string } {
  if (aqi <= 50)  return { label: 'Good',                  color: '#3fb950' };
  if (aqi <= 100) return { label: 'Moderate',              color: '#d29922' };
  if (aqi <= 150) return { label: 'Unhealthy (sensitive)', color: '#f0883e' };
  if (aqi <= 200) return { label: 'Unhealthy',             color: '#f85149' };
  return               { label: 'Hazardous',               color: '#b44ac0' };
}

// ─── WMO weather code → label + emoji ────────────────────────────────────────

function describeCode(code: number): { label: string; emoji: string } {
  if (code === 0)  return { label: 'Clear sky',     emoji: '☀️' };
  if (code === 1)  return { label: 'Mainly clear',  emoji: '🌤️' };
  if (code === 2)  return { label: 'Partly cloudy', emoji: '⛅' };
  if (code === 3)  return { label: 'Overcast',      emoji: '☁️' };
  if (code <= 48)  return { label: 'Fog',           emoji: '🌫️' };
  if (code <= 55)  return { label: 'Drizzle',       emoji: '🌦️' };
  if (code <= 65)  return { label: 'Rain',          emoji: '🌧️' };
  if (code <= 75)  return { label: 'Snow',          emoji: '❄️' };
  if (code === 77) return { label: 'Snow grains',   emoji: '🌨️' };
  if (code <= 82)  return { label: 'Rain showers',  emoji: '🌧️' };
  if (code <= 86)  return { label: 'Snow showers',  emoji: '🌨️' };
  return                  { label: 'Thunderstorm',  emoji: '⛈️' };
}

function dayName(dateStr: string, index: number): string {
  if (index === 0) return 'Today';
  if (index === 1) return 'Tomorrow';
  return new Date(dateStr).toLocaleDateString('en-GB', { weekday: 'short', month: 'short', day: 'numeric' });
}

function dayShort(dateStr: string, index: number): string {
  if (index === 0) return 'Today';
  return new Date(dateStr).toLocaleDateString('en-GB', { weekday: 'short' });
}

// ─── SVG chart helpers ────────────────────────────────────────────────────────

const ACCENT     = '#58a6ff';
const ACCENT_DIM = 'rgba(88,166,255,0.15)';
const ACCENT2    = '#ff7b72';   // apparent temperature line
const GRID       = 'rgba(255,255,255,0.06)';
const TEXT_MUTED = '#8b949e';

// Green → yellow → orange → red based on wind speed (km/h)
const WIND_SCALE = [
  { threshold: 0,  color: '#3fb950' },
  { threshold: 15, color: '#7ee787' },
  { threshold: 25, color: '#d29922' },
  { threshold: 38, color: '#f0883e' },
  { threshold: 50, color: '#f85149' },
];

function windColor(speed: number): string {
  let color = WIND_SCALE[0].color;
  for (const step of WIND_SCALE) {
    if (speed >= step.threshold) color = step.color;
    else break;
  }
  return color;
}

