const WIND_LEGEND = [
  { label: '0–14',  color: '#3fb950' },
  { label: '15–24', color: '#7ee787' },
  { label: '25–37', color: '#d29922' },
  { label: '38–49', color: '#f0883e' },
  { label: '50+',   color: '#f85149' },
] as const;

/** Smooth bezier path through points (Catmull-Rom → cubic bezier) */
function smoothPath(pts: { x: number; y: number }[], tension = 0.35): string {
  if (pts.length < 2) return '';
  let d = `M ${pts[0].x.toFixed(2)} ${pts[0].y.toFixed(2)}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0  = pts[Math.max(i - 1, 0)];
    const p1  = pts[i];
    const p2  = pts[i + 1];
    const p3  = pts[Math.min(i + 2, pts.length - 1)];
    const cp1x = p1.x + (p2.x - p0.x) * tension;
    const cp1y = p1.y + (p2.y - p0.y) * tension;
    const cp2x = p2.x - (p3.x - p1.x) * tension;
    const cp2y = p2.y - (p3.y - p1.y) * tension;
    d += ` C ${cp1x.toFixed(2)} ${cp1y.toFixed(2)} ${cp2x.toFixed(2)} ${cp2y.toFixed(2)} ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
  }
  return d;
}

/** Arrow polygon pointing "up" then rotated by degrees */
function WindArrow({ cx, cy, deg, size = 7 }: { cx: number; cy: number; deg: number; size?: number }) {
  return (
    <g transform={`translate(${cx},${cy}) rotate(${deg})`}>
      <polygon
        points={`0,${-size} ${size * 0.55},${size * 0.6} 0,${size * 0.2} ${-size * 0.55},${size * 0.6}`}
        fill={ACCENT}
        opacity={0.85}
      />
    </g>
  );
}

// ─── Temperature line chart (today, hourly) ───────────────────────────────────

interface TempLineChartProps {
  temps:      number[]; // 24 values — actual temperature
  feelsLike:  number[]; // 24 values — apparent temperature
}

function TempLineChart({ temps, feelsLike }: TempLineChartProps) {
  const W   = 268, H = 88;
  const PAD = { t: 14, b: 22, l: 32, r: 8 };
  const plotW = W - PAD.l - PAD.r;
  const plotH = H - PAD.t - PAD.b;

  const allVals = [...temps, ...feelsLike];
  const minVal  = Math.floor(Math.min(...allVals) / 5) * 5;
  const maxVal  = Math.ceil(Math.max(...allVals) / 5) * 5;
  const range   = maxVal - minVal || 1;

  const toPoint = (vals: number[]) =>
    vals.map((v, i) => ({
      x: PAD.l + (i / (vals.length - 1)) * plotW,
      y: PAD.t + plotH - ((v - minVal) / range) * plotH,
    }));

  const tempPts   = toPoint(temps);
  const feelsPts  = toPoint(feelsLike);
  const tempPath  = smoothPath(tempPts);
  const feelsPath = smoothPath(feelsPts);
  const areaPath  = `${tempPath} L ${tempPts[tempPts.length - 1].x.toFixed(2)} ${(PAD.t + plotH).toFixed(2)} L ${tempPts[0].x.toFixed(2)} ${(PAD.t + plotH).toFixed(2)} Z`;

  const xLabels = [0, 6, 12, 18, 23].map((h) => ({
    label: h === 23 ? '24h' : `${h}h`,
    x:     PAD.l + (h / (temps.length - 1)) * plotW,
  }));

  const yLabels = [
    { label: `${maxVal}°`, y: PAD.t },
    { label: `${Math.round((maxVal + minVal) / 2)}°`, y: PAD.t + plotH / 2 },
    { label: `${minVal}°`, y: PAD.t + plotH },
  ];

  const nowH = new Date().getHours();
  const nowPt = tempPts[Math.min(nowH, tempPts.length - 1)];

  return (
    <>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block', overflow: 'visible' }}>
        <defs>
          <linearGradient id="tempGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stopColor={ACCENT} stopOpacity={0.25} />
            <stop offset="100%" stopColor={ACCENT} stopOpacity={0} />
          </linearGradient>
        </defs>

        {/* grid */}
        {yLabels.map(({ y }) => (
          <line key={y} x1={PAD.l} y1={y} x2={PAD.l + plotW} y2={y} stroke={GRID} strokeWidth={1} />
        ))}

        {/* area fill */}
        <path d={areaPath} fill="url(#tempGrad)" />

        {/* feels-like dashed */}
        <path d={feelsPath} fill="none" stroke={ACCENT2} strokeWidth={1} strokeDasharray="3 4" opacity={0.6} />

        {/* actual temperature */}
        <path d={tempPath} fill="none" stroke={ACCENT} strokeWidth={1.5} strokeLinejoin="round" />

        {/* current hour dot */}
        <circle cx={nowPt.x} cy={nowPt.y} r={3} fill={ACCENT} />

        {/* x labels */}
        {xLabels.map(({ label, x }) => (
          <text key={label} x={x} y={H - 4} textAnchor="middle" fill={TEXT_MUTED} fontSize={9} fontFamily="monospace">
            {label}
          </text>
        ))}

        {/* y labels */}
        {yLabels.map(({ label, y }) => (
          <text key={label} x={PAD.l - 4} y={y + 3} textAnchor="end" fill={TEXT_MUTED} fontSize={9} fontFamily="monospace">
            {label}
          </text>
        ))}
      </svg>

      {/* legend */}
      <LegendRow>
        <LegendItem><LegendSwatch color={ACCENT} /> Actual</LegendItem>
        <LegendItem style={{ marginLeft: 4 }}>
          <LegendSwatch color={ACCENT2} style={{ opacity: 0.6 }} /> Feels like
        </LegendItem>
      </LegendRow>
    </>
  );
}

// ─── Wind line chart (today, hourly) ─────────────────────────────────────────

interface WindLineChartProps {
  speeds: number[];
}

function WindLineChart({ speeds }: WindLineChartProps) {
  const W   = 268, H = 88;
  const PAD = { t: 14, b: 22, l: 28, r: 8 };
  const plotW = W - PAD.l - PAD.r;
  const plotH = H - PAD.t - PAD.b;
  const max  = Math.max(...speeds, 1);
  const ceil = Math.ceil(max / 5) * 5;

  const pts = speeds.map((v, i) => ({
    x: PAD.l + (i / (speeds.length - 1)) * plotW,
    y: PAD.t + plotH - (v / ceil) * plotH,
  }));

  const linePath = smoothPath(pts);
  const areaPath = `${linePath} L ${pts[pts.length - 1].x.toFixed(2)} ${(PAD.t + plotH).toFixed(2)} L ${pts[0].x.toFixed(2)} ${(PAD.t + plotH).toFixed(2)} Z`;

  const xLabels = [0, 6, 12, 18, 23].map((h) => ({
    label: h === 23 ? '24h' : `${h}h`,
    x:     PAD.l + (h / (speeds.length - 1)) * plotW,
  }));

  const yLabels = [
    { label: `${ceil}`,                   y: PAD.t },
    { label: `${Math.round(ceil / 2)}`,   y: PAD.t + plotH / 2 },
    { label: '0',                          y: PAD.t + plotH },
  ];

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block', overflow: 'visible' }}>
      <defs>
        <linearGradient id="windGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%"   stopColor={ACCENT} stopOpacity={0.3} />
          <stop offset="100%" stopColor={ACCENT} stopOpacity={0} />
        </linearGradient>
      </defs>
      {yLabels.map(({ y }) => (
        <line key={y} x1={PAD.l} y1={y} x2={PAD.l + plotW} y2={y} stroke={GRID} strokeWidth={1} />
      ))}
      <path d={areaPath} fill="url(#windGrad)" />
      <path d={linePath} fill="none" stroke={ACCENT} strokeWidth={1.5} strokeLinejoin="round" />
      {(() => {
        const now = new Date().getHours();
        const p   = pts[Math.min(now, pts.length - 1)];
        return <circle cx={p.x} cy={p.y} r={3} fill={ACCENT} />;
      })()}
      {xLabels.map(({ label, x }) => (
        <text key={label} x={x} y={H - 4} textAnchor="middle" fill={TEXT_MUTED} fontSize={9} fontFamily="monospace">
          {label}
        </text>
      ))}
      {yLabels.map(({ label, y }) => (
        <text key={label} x={PAD.l - 4} y={y + 3} textAnchor="end" fill={TEXT_MUTED} fontSize={9} fontFamily="monospace">
          {label}
        </text>
      ))}
    </svg>
  );
}

// ─── Wind bar chart (this week) ───────────────────────────────────────────────

interface WindBarChartProps {
  speeds:     number[];
  directions: number[];
  dayLabels:  string[];
}

function WindBarChart({ speeds, directions, dayLabels }: WindBarChartProps) {
  const W = 268, H = 110;
  const ARROW_CY = 7;
  const LABEL_Y  = 23;
  const BAR_TOP  = 30;
  const BAR_BOT  = 90;
  const DAY_Y    = 106;
  const plotH    = BAR_BOT - BAR_TOP;

  const W_PAD = 8;
  const plotW  = W - W_PAD * 2;
  const n      = speeds.length;
  const max    = Math.max(...speeds, 1);
  const ceil   = Math.ceil(max / 5) * 5;
  const barW   = plotW / n;
  const gap    = barW * 0.28;

  return (
    <>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block', overflow: 'visible' }}>
        <line x1={W_PAD} y1={BAR_BOT} x2={W_PAD + plotW} y2={BAR_BOT} stroke={GRID} strokeWidth={1} />
        {speeds.map((v, i) => {
          const barH  = (v / ceil) * plotH;
          const x     = W_PAD + i * barW + gap / 2;
          const bw    = barW - gap;
          const by    = BAR_BOT - barH;
          const cx    = x + bw / 2;
          const color = windColor(v);
          return (
            <g key={i}>
              <WindArrow cx={cx} cy={ARROW_CY} deg={directions[i]} size={6} />
              <text x={cx} y={LABEL_Y} textAnchor="middle" fill={color} fontSize={8} fontWeight="600" fontFamily="monospace">
                {Math.round(v)}
              </text>
              <rect x={x} y={by} width={bw} height={barH} fill={color} opacity={0.85} rx={2} />
              <text x={cx} y={DAY_Y} textAnchor="middle" fill={TEXT_MUTED} fontSize={9} fontFamily="monospace">
                {dayLabels[i]}
              </text>
            </g>
          );
        })}
        <text x={W - W_PAD} y={BAR_BOT - 2} textAnchor="end" fill={TEXT_MUTED} fontSize={8} fontFamily="monospace">
          km/h
        </text>
      </svg>
      <LegendRow>
        {WIND_LEGEND.map(({ label, color }) => (
          <LegendItem key={label}><LegendSwatch color={color} />{label}</LegendItem>
        ))}
      </LegendRow>
    </>
  );
}

