// ─── Component ────────────────────────────────────────────────────────────────

interface Place {
  id:   string;
  name: string;
  lat:  number;
  lng:  number;
}

interface WeatherPanelProps {
  place:   Place | null;
  onClose: () => void;
}

export function WeatherPanel({ place, onClose }: WeatherPanelProps) {
  const [data,       setData]       = useState<WeatherData | null>(null);
  const [aqiData,    setAqiData]    = useState<AqiData | null>(null);
  const [loading,    setLoading]    = useState(false);
  const [error,      setError]      = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);

  useEffect(() => {
    if (!place) { setData(null); setAqiData(null); return; }

    setLoading(true);
    setError(null);
    setData(null);
    setAqiData(null);

    const weatherUrl =
      `https://api.open-meteo.com/v1/forecast` +
      `?latitude=${place.lat}&longitude=${place.lng}` +
      `&current_weather=true` +
      `&hourly=temperature_2m,apparent_temperature,relativehumidity_2m,windspeed_10m,winddirection_10m` +
      `&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_sum,windspeed_10m_max,winddirection_10m_dominant` +
      `&timezone=auto&forecast_days=7`;

    const aqiUrl =
      `https://air-quality-api.open-meteo.com/v1/air-quality` +
      `?latitude=${place.lat}&longitude=${place.lng}` +
      `&current=pm2_5,pm10,european_aqi,us_aqi`;

    Promise.all([
      fetch(weatherUrl).then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() as Promise<WeatherData>; }),
      fetch(aqiUrl).then((r) => r.ok ? r.json() as Promise<AqiData> : null).catch(() => null),
    ])
      .then(([weather, aqi]) => {
        setData(weather);
        setAqiData(aqi);
        setLoading(false);
      })
      .catch((e: Error) => { setError(e.message); setLoading(false); });

  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [place?.id, retryCount]);

  const current = data ? describeCode(data.current_weather.weathercode) : null;

  // Today's 24 hourly values
  const todayHourlyWind  = data ? data.hourly.windspeed_10m.slice(0, 24) : [];
  const todayHourlyTemp  = data ? data.hourly.temperature_2m.slice(0, 24) : [];
  const todayFeelsLike   = data ? data.hourly.apparent_temperature.slice(0, 24) : [];

  // Current hour's humidity
  const nowH     = new Date().getHours();
  const humidity = data ? data.hourly.relativehumidity_2m[nowH] : null;

  // Current hour's feels-like
  const feelsNow = data ? data.hourly.apparent_temperature[nowH] : null;

  // AQI
  const aqiBadge = aqiData ? aqiLabel(aqiData.current.us_aqi) : null;

  return (
    <Panel visible={!!place}>
      <Header>
        <PlaceName>{place?.name ?? ''}</PlaceName>
        <CloseBtn onClick={onClose} title="Close">✕</CloseBtn>
      </Header>

      <Scroll>
        {loading && <StateMsg>Loading weather…</StateMsg>}
        {error && (
          <StateMsg>
            <div>Weather unavailable — the API may be temporarily down.</div>
            <button
              onClick={() => setRetryCount((c) => c + 1)}
              style={{
                marginTop: 12, padding: '6px 16px', cursor: 'pointer',
                background: 'none', border: `1px solid ${theme.colors.border}`,
                borderRadius: 6, color: theme.colors.mainText,
                fontFamily: 'inherit', fontSize: 12,
              }}
            >
              Retry
            </button>
          </StateMsg>
        )}

        {data && current && (
          <>
            {/* ── Current conditions ── */}
            <CurrentCard>
              <CurrentTop>
                <div>
                  <CurrentTemp>{Math.round(data.current_weather.temperature)}°C</CurrentTemp>
                  <CurrentLabel>{current.label}</CurrentLabel>
                </div>
                <CurrentEmoji>{current.emoji}</CurrentEmoji>
              </CurrentTop>
              <StatRow>
                <Stat>💨 {Math.round(data.current_weather.windspeed)} km/h</Stat>
                <Stat>
                  🌡 {Math.round(data.daily.temperature_2m_max[0])}° / {Math.round(data.daily.temperature_2m_min[0])}°
                </Stat>
                {feelsNow != null && (
                  <Stat>🌬 Feels {Math.round(feelsNow)}°</Stat>
                )}
                {humidity != null && (
                  <Stat>💧 {humidity}% RH</Stat>
                )}
              </StatRow>
              {aqiBadge && aqiData && (
                <AqiBadge color={aqiBadge.color}>
                  🏭 AQI {aqiData.current.us_aqi} · {aqiBadge.label}
                </AqiBadge>
              )}
            </CurrentCard>

            {/* ── Temperature — today (hourly) ── */}
            {todayHourlyTemp.length > 0 && (
              <div>
                <SectionTitle>Temperature today (hourly)</SectionTitle>
                <ChartCard>
                  <ChartLabel>°C · dot = current hour</ChartLabel>
                  <TempLineChart temps={todayHourlyTemp} feelsLike={todayFeelsLike} />
                </ChartCard>
              </div>
            )}

            {/* ── Wind — today (hourly) ── */}
            <div>
              <SectionTitle>Wind today (hourly)</SectionTitle>
              <ChartCard>
                <ChartLabel>Speed km/h · dot = current hour</ChartLabel>
                <WindLineChart speeds={todayHourlyWind} />
              </ChartCard>
            </div>

            {/* ── Wind — this week (daily max + direction) ── */}
            <div>
              <SectionTitle>Wind this week (daily max)</SectionTitle>
              <ChartCard>
                <ChartLabel>Max speed km/h · arrows = dominant direction</ChartLabel>
                <WindBarChart
                  speeds={data.daily.windspeed_10m_max}
                  directions={data.daily.winddirection_10m_dominant}
                  dayLabels={data.daily.time.map((d, i) => dayShort(d, i))}
                />
              </ChartCard>
            </div>

            {/* ── 7-Day forecast ── */}
            <div>
              <SectionTitle>7-Day Forecast</SectionTitle>
              {data.daily.time.map((dateStr, i) => {
                const { emoji, label } = describeCode(data.daily.weathercode[i]);
                return (
                  <DayRow key={dateStr}>
                    <DayEmoji>{emoji}</DayEmoji>
                    <DayInfo>
                      <DayName>{dayName(dateStr, i)}</DayName>
                      <DayDesc>{label}</DayDesc>
                    </DayInfo>
                    <Rain>
                      {data.daily.precipitation_sum[i] > 0 && (
                        <>💧 {data.daily.precipitation_sum[i].toFixed(1)}</>
                      )}
                    </Rain>
                    <DayTemps>
                      <TempHigh>{Math.round(data.daily.temperature_2m_max[i])}°</TempHigh>
                      <TempLow>{Math.round(data.daily.temperature_2m_min[i])}°</TempLow>
                    </DayTemps>
                  </DayRow>
                );
              })}
            </div>
          </>
        )}
      </Scroll>
    </Panel>
  );
}
