import { useCallback, useEffect, useRef } from 'react';

const RAINVIEWER_API = 'https://api.rainviewer.com/public/weather-maps.json';
const REFRESH_MS     = 5 * 60_000; // refresh tile URL every 5 min

interface RainViewerFrame { time: number; path: string; }
interface RainViewerData {
  host:  string;
  radar: { past: RainViewerFrame[]; nowcast: RainViewerFrame[] };
}

interface WeatherRadarLayerProps {
  map:     import('leaflet').Map | null;
  enabled: boolean;
}

export function WeatherRadarLayer({ map, enabled }: WeatherRadarLayerProps) {
  const tileRef = useRef<import('leaflet').TileLayer | null>(null);

  const clearAll = useCallback(() => {
    tileRef.current?.remove();
    tileRef.current = null;
  }, []);

  const fetchAndRender = useCallback(async () => {
    if (!map || !enabled) return;

    try {
      const res = await fetch(RAINVIEWER_API);
      if (!res.ok) return;
      const data = await res.json() as RainViewerData;
      if (!map || !enabled) return;

      const frames = data.radar.past;
      if (!frames?.length) return;

      const latest = frames[frames.length - 1];
      // colour scheme 2, smooth 1, snow 1
      const url = `${data.host}${latest.path}/256/{z}/{x}/{y}/2/1_1.png`;

      tileRef.current?.remove();
      tileRef.current = window.L.tileLayer(url, {
        opacity:     0.6,
        attribution: '<a href="https://www.rainviewer.com">RainViewer</a>',
      }).addTo(map);
    } catch {
      // ignore
    }
  }, [map, enabled]);

  useEffect(() => {
    if (!enabled) { clearAll(); return; }

    fetchAndRender();
    const id = setInterval(fetchAndRender, REFRESH_MS);
    return () => { clearInterval(id); clearAll(); };
  }, [enabled, fetchAndRender, clearAll]);

  return null;
}
